import createRaw from '../build/host.gen.ts';

// The earlier tests never pause: their node() checks paused is false and drops it.
async function create() {
  const h = await createRaw();
  return Object.assign(Object.create(h), {
    async node() {
      const { paused, ...rest } = await h.node();
      assert.equal(paused, false);
      return rest;
    },
  });
}

test('pause', async () => {
  const h = await createRaw();
  assert.equal((await h.resume()).ok, false);
  assert.deepEqual(await h.pause(), { ok: true });
  assert.equal((await h.pause()).ok, false);
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody', paused: true });
  assert.deepEqual(await h.voteRequested('n1', 1), { ok: true });
  assert.deepEqual(await h.newerTermSeen(2), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'nobody', paused: true });
  assert.deepEqual(await h.resume(), { ok: true });
  assert.equal((await h.resume()).ok, false);
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.equal((await h.pause()).ok, false);
  await h.electionWon();
  assert.equal((await h.pause()).ok, false);
  assert.deepEqual(await h.node(), { role: 'leader', term: 3, votedFor: 'itself', paused: false });
});

